export function getPartVoiceClipKey(kind: ElectricPartKind): string {
  if (kind === 'aa_battery' || kind === 'battery_9v' || kind === 'dual_battery') return 'part_battery';
  if (kind === 'solar_panel') return 'part_solar';
  if (kind === 'hand_dynamo') return 'part_dynamo';
  if (kind === 'armature') return 'part_armature';
  if (kind === 'fan' || kind === 'exhaust_fan') return 'part_fan';
  if (kind.startsWith('bulb') || kind === 'ceiling_lamp' || kind === 'chandelier_dual' || kind === 'led_disco')
    return 'part_bulb';
  if (kind === 'buzzer' || kind === 'doorbell_chime' || kind === 'siren') return 'part_buzzer';
  if (kind === 'toy_car' || kind === 'crane_winch') return 'part_car';
  if (kind === 'robot_buddy') return 'part_robot';
  if (kind === 'electromagnet') return 'part_electromagnet';
  if (kind === 'mcb_breaker' || kind === 'fuse_box') return 'part_breaker';
  if (kind === 'wall_outlet') return 'part_outlet';
  return 'part_switch';
}

export function getChemPourVoiceKey(ing: ChemIngredientId): string | null {
  switch (ing) {
    case 'cola':
    case 'orange_soda':
      return 'chem_pour_cola';
    case 'salt':
      return 'chem_pour_salt';
    case 'baking_soda':
      return 'chem_pour_baking_soda';
    case 'vinegar':
      return 'chem_pour_vinegar';
    case 'lemon_juice':
      return 'chem_pour_lemon';
    case 'oil':
      return 'chem_pour_oil';
    case 'dish_soap':
      return 'chem_pour_soap';
    default:
      return null;
  }
}

export function getWinExplanationForLevel(level: GameLevel): {
  clipKey: string;
  fullText: string;
} {
  if (level.lab === 'electric') {
    const el = level as ElectricLevel;
    const kinds = el.slots.map((s) => s.partKind);
    if (kinds.includes('wall_outlet')) {
      return {
        clipKey: 'win_elec_wall_outlet',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_wall_outlet,
      };
    }
    if (kinds.includes('wall_switch_1') || kinds.includes('wall_switch_2') || kinds.includes('stair_switch_a')) {
      return {
        clipKey: 'win_elec_wall_switch',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_wall_switch,
      };
    }
    if (kinds.includes('electromagnet')) {
      return {
        clipKey: 'win_elec_electromagnet',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_electromagnet,
      };
    }
    if (kinds.includes('solar_panel') || kinds.includes('hand_dynamo')) {
      return {
        clipKey: 'win_elec_solar_dynamo',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_solar_dynamo,
      };
    }
    if (kinds.includes('armature')) {
      return {
        clipKey: 'win_elec_armature',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_armature,
      };
    }
    if (kinds.includes('fan')) {
      return {
        clipKey: 'win_elec_fan',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_fan,
      };
    }
    if (kinds.includes('buzzer') || kinds.includes('doorbell_chime') || kinds.includes('siren')) {
      return {
        clipKey: 'win_elec_buzzer',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_buzzer,
      };
    }
    if (kinds.includes('toy_car') || kinds.includes('robot_buddy') || kinds.includes('crane_winch')) {
      return {
        clipKey: 'win_elec_car_robot',
        fullText: OFFLINE_VOICE_CLIPS.win_elec_car_robot,
      };
    }
    return {
      clipKey: 'win_elec_bulb',
      fullText: OFFLINE_VOICE_CLIPS.win_elec_bulb,
    };
  }

  if (level.lab === 'chemistry') {
    const ch = level as ChemistryLevel;
    const eff = ch.vessels[0]?.resultEffect;
    if (eff === 'balloon_inflate') {
      return { clipKey: 'win_chem_balloon', fullText: OFFLINE_VOICE_CLIPS.win_chem_balloon };
    }
    if (eff === 'volcano_eruption') {
      return { clipKey: 'win_chem_volcano', fullText: OFFLINE_VOICE_CLIPS.win_chem_volcano };
    }
    if (eff === 'foam_geyser') {
      return { clipKey: 'win_chem_foam_soda', fullText: OFFLINE_VOICE_CLIPS.win_chem_foam_soda };
    }
    if (eff === 'density_layers' || eff === 'lava_lamp') {
      return { clipKey: 'win_chem_density_lava', fullText: OFFLINE_VOICE_CLIPS.win_chem_density_lava };
    }
    if (eff === 'magic_milk' || eff === 'pepper_scatter') {
      return { clipKey: 'win_chem_magic_milk', fullText: OFFLINE_VOICE_CLIPS.win_chem_magic_milk };
    }
    if (eff === 'ph_color_shift') {
      return { clipKey: 'win_chem_cabbage_ph', fullText: OFFLINE_VOICE_CLIPS.win_chem_cabbage_ph };
    }
    if (eff === 'dancing_raisins') {
      return { clipKey: 'win_chem_raisins', fullText: OFFLINE_VOICE_CLIPS.win_chem_raisins };
    }
    if (eff === 'ice_fishing' || eff === 'crystal_sparkle') {
      return { clipKey: 'win_chem_ice_crystal', fullText: OFFLINE_VOICE_CLIPS.win_chem_ice_crystal };
    }
    if (eff === 'slime_oobleck') {
      return { clipKey: 'win_chem_slime', fullText: OFFLINE_VOICE_CLIPS.win_chem_slime };
    }
    if (eff === 'water_filter') {
      return { clipKey: 'win_chem_filter', fullText: OFFLINE_VOICE_CLIPS.win_chem_filter };
    }
    if (eff === 'dissolve_calm') {
      return { clipKey: 'win_chem_dissolve', fullText: OFFLINE_VOICE_CLIPS.win_chem_dissolve };
    }
    return { clipKey: 'win_chem_color_mix', fullText: OFFLINE_VOICE_CLIPS.win_chem_color_mix };
  }

  const ph = level as PhysicsLevel;
  switch (ph.mode) {
    case 'magnet_explore':
      return { clipKey: 'win_phys_magnet', fullText: OFFLINE_VOICE_CLIPS.win_phys_magnet };
    case 'magnet_poles':
      return { clipKey: 'win_phys_poles', fullText: OFFLINE_VOICE_CLIPS.win_phys_poles };
    case 'sink_float':
      return { clipKey: 'win_phys_sink_float', fullText: OFFLINE_VOICE_CLIPS.win_phys_sink_float };
    case 'static_balloon':
      return { clipKey: 'win_phys_static', fullText: OFFLINE_VOICE_CLIPS.win_phys_static };
    case 'balance_scale':
      return { clipKey: 'win_phys_scale', fullText: OFFLINE_VOICE_CLIPS.win_phys_scale };
    case 'light_prism':
      return { clipKey: 'win_phys_prism', fullText: OFFLINE_VOICE_CLIPS.win_phys_prism };
    case 'ramp_friction':
      return { clipKey: 'win_phys_ramp', fullText: OFFLINE_VOICE_CLIPS.win_phys_ramp };
    case 'wind_energy':
      return { clipKey: 'win_phys_wind', fullText: OFFLINE_VOICE_CLIPS.win_phys_wind };
    case 'sound_glasses':
      return { clipKey: 'win_phys_sound', fullText: OFFLINE_VOICE_CLIPS.win_phys_sound };
    case 'plant_growth':
      return { clipKey: 'win_phys_plant', fullText: OFFLINE_VOICE_CLIPS.win_phys_plant };
  }
}

export function getStartClipForLevel(level: GameLevel): string {
  if (level.lab === 'electric') return 'elec_step_place';
  if (level.lab === 'chemistry') return 'chem_step_start';
  const ph = level as PhysicsLevel;
  switch (ph.mode) {
    case 'magnet_explore':
      return 'phys_step_magnet';
    case 'magnet_poles':
      return 'phys_step_poles';
    case 'sink_float':
      return 'phys_step_sink_float';
    case 'static_balloon':
      return 'phys_step_balloon';
    case 'balance_scale':
      return 'phys_step_scale';
    case 'light_prism':
      return 'phys_step_prism';
    case 'ramp_friction':
      return 'phys_step_ramp';
    case 'wind_energy':
      return 'phys_step_wind';
    case 'sound_glasses':
      return 'phys_step_sound';
    case 'plant_growth':
      return 'phys_step_plant';
  }
}
